edits.old:
while (head != nullptr) {
    Node* following = head->next;  // read the link BEFORE deleting the node that holds it
    delete head;
    head = following;
}

edits.new:
if (head == nullptr) return;
free_list(head->next);
delete head;

edits.old:
Node* prev = nullptr;
while (head != nullptr) {
    Node* following = head->next;  // remember the rest before overwriting the link
    head->next = prev;
    prev = head;
    head = following;
}
return prev;

edits.new:
Node* out = nullptr;
for (const Node* p = head; p != nullptr; p = p->next) out = new Node{p->value, out};
return out;
